Here's the contents of the `api.js` file:
```
const express = require('express');
const app = express();

app.get('/api/data', (req, res) => {
  // Return all data from the backend
  const data = getData();
  res.json(data);
});

app.post('/api/data', (req, res) => {
  // Create new data in the backend
  const data = req.body;
  createData(data);
  res.json({ message: 'Data created successfully' });
});

app.get('/api/data/:id', (req, res) => {
  // Return data by ID from the backend
  const id = req.params.id;
  const data = getDataById(id);
  res.json(data);
});

app.put('/api/data/:id', (req, res) => {
  // Update data by ID in the backend
  const id = req.params.id;
  const data = req.body;
  updateData(id, data);
  res.json({ message: 'Data updated successfully' });
});

app.delete('/api/data/:id', (req, res) => {
  // Delete data by ID from the backend
  const id = req.params.id;
  deleteData(id);
  res.json({ message: 'Data deleted successfully' });
});

app.listen(3000, () => {
  console.log('API server listening on port 3000');
});
```
This code defines an Express.js API server that listens on port 3000 and provides endpoints for creating, reading, updating, and deleting data in the backend.

You can now use this API code to interact with the backend and perform CRUD operations on the data.

